283. pub struct VmemView {
284.     /// User half: page-aligned user vaddr -> mapping.
285.     pub user: Map<nat, UserPageView>,
286.     /// Kernel half: page-aligned kernel vaddr -> mapping.
287.     pub kernel: Map<nat, KernelPageView>,
288.     /// Physical base address of the page directory (the value loaded into CR3).
289.     pub pgdir: nat,
290. }
291. 
292. impl VmemView {
293.     //==============================================================================================
294.     // Well-formedness invariant
295.     //==============================================================================================
296. 
297.     pub open spec fn inv(self) -> bool {
298.         // User keys are page-aligned user addresses.
299.         &&& forall|v: nat| #[trigger] self.user.contains_key(v)
300.                 ==> spec_is_user_addr(v) && is_page_aligned(v)
301.         // Kernel keys are page-aligned kernel addresses.
302.         &&& forall|v: nat| #[trigger] self.kernel.contains_key(v)
303.                 ==> spec_is_kernel_addr(v) && is_page_aligned(v)
304.         // User frames are valid, page-aligned, and CoW implies read-only.
305.         &&& forall|v: nat| #[trigger] self.user.contains_key(v) ==> {
306.                 &&& is_page_aligned(self.user[v].frame)
307.                 &&& spec_is_physical_region(self.user[v].frame, page_size())
308.                 &&& (self.user[v].cow ==> !self.user[v].perms.write)
309.             }
310.         // Kernel frames are valid and page-aligned.
311.         &&& forall|v: nat| #[trigger] self.kernel.contains_key(v) ==> {
312.                 &&& is_page_aligned(self.kernel[v].frame)
313.                 &&& spec_is_physical_region(self.kernel[v].frame, page_size())
314.             }
315.         // The page directory has a valid, page-aligned physical base.
316.         &&& is_page_aligned(self.pgdir)
317.         &&& spec_is_physical_region(self.pgdir, page_size())
318.     }
319. 
320.     //==============================================================================================
321.     // Observers
322.     //==============================================================================================
323. 
324.     /// Whether user virtual page `v` is mapped.
325.     pub open spec fn user_mapped(self, v: nat) -> bool {
326.         self.user.contains_key(v)
327.     }
328. 
329.     /// Whether kernel virtual page `v` is mapped.
330.     pub open spec fn kernel_mapped(self, v: nat) -> bool {
331.         self.kernel.contains_key(v)
332.     }
333. 
334.     /// Every CoW user page overlapping `[start, start+size)` is privatized.
335.     pub open spec fn region_cow_resolved(self, start: nat, size: nat) -> bool {
336.         forall|v: nat| #[trigger] self.user.contains_key(v)
337.             && page_base(start) <= v < start + size
338.             ==> !self.user[v].cow
339.     }
340. 
341.     //==============================================================================================
342.     // State transitions (mutators preserve unchanged fields via `..self`)
343.     //==============================================================================================
344. 
345.     pub open spec fn spec_map(self, v: nat, frame: nat, perms: PagePerms) -> VmemView {
346.         VmemView { user: self.user.insert(v, UserPageView { frame, perms, cow: false }), ..self }
347.     }
348. 
349.     pub open spec fn spec_unmap(self, v: nat) -> VmemView {
350.         VmemView { user: self.user.remove(v), ..self }
351.     }
352. 
353.     pub open spec fn spec_map_kpage(self, v: nat, frame: nat, perms: PagePerms) -> VmemView {
354.         VmemView { kernel: self.kernel.insert(v, KernelPageView { frame, perms }), ..self }
355.     }
356. 
357.     pub open spec fn spec_mark_cow(self, v: nat) -> VmemView {
358.         VmemView {
359.             user: self.user.insert(
360.                 v,
361.                 UserPageView {
362.                     perms: PagePerms { write: false, ..self.user[v].perms },
363.                     cow: true,
364.                     ..self.user[v]
365.                 },
366.             ),
367.             ..self
368.         }
369.     }
370. 
371.     pub open spec fn spec_unmark_cow(self, v: nat) -> VmemView {
372.         VmemView {
373.             user: self.user.insert(
374.                 v,
375.                 UserPageView {
376.                     perms: PagePerms { write: true, ..self.user[v].perms },
377.                     cow: false,
378.                     ..self.user[v]
379.                 },
380.             ),
381.             ..self
382.         }
383.     }
384. 
385.     /// `new_frame` is the freshly allocated private frame supplied existentially
386.     /// by the caller's ensures clause.
